WITH base AS (SELECT *, CAST(rating AS INT) AS rating_int, CONCAT(city, ' ', supplier_name) AS city_supplier_name FROM suppliers WHERE city IS NOT NULL) SELECT id, country, city, rating_int, city_supplier_name, LAG(rating_int) OVER w_grp AS prev_rating_int, LEAD(rating) OVER w_grp AS next_rating, ROW_NUMBER() OVER w_grp AS event_seq FROM base WHERE city NOT IN ('London', 'Tokyo', 'Singapore') WINDOW w_grp AS (PARTITION BY country, city ORDER BY rating, id);
